testo:
{
 "genere": "prevedi",
 "titolo": "Ripasso: Gioco completo",
 "consegna": "Leggi ogni pezzo di codice e scrivi cosa restituisce `run()`, senza eseguirlo. Poi confronta con la risposta vera.",
 "modalita": "previsioni",
 "previsioni": [
  {
   "codice": "extends RefCounted


func run():
	var current_health: int = 15
	var damage: int = 20
	var final_health := maxi(0, current_health - damage)
	return final_health
",
   "domanda": "Quanto vale `final_health`?",
   "spiegazione": "`current_health - damage` fa `-5`. La funzione `maxi(0, -5)` sceglie il valore massimo tra 0 e -5, quindi restituisce `0`."
  },
  {
   "codice": "extends RefCounted


func run():
	var upgrades: Array[String] = ["speed_up", "damage_up", "heal"]
	upgrades.remove_at(1)
	return upgrades.size()
",
   "domanda": "Quanto vale `upgrades.size()` alla fine?",
   "spiegazione": "L'array parte con 3 elementi. `remove_at(1)` rimuove l'elemento all'indice 1 ("damage_up"). Ne restano 2, quindi la dimensione è 2."
  },
  {
   "codice": "extends RefCounted


func run():
	var high_score: int = 100
	var new_score: int = 150
	if new_score > high_score:
		high_score = new_score
	return high_score
",
   "domanda": "Quanto vale `high_score` alla fine?",
   "spiegazione": "`new_score` (150) è maggiore di `high_score` (100). La condizione `if` risulta vera, quindi `high_score` viene aggiornato a 150."
  },
  {
   "codice": "extends RefCounted


func run():
	var is_paused: bool = false
	is_paused = not is_paused
	var text: String = "Stato: " + ("Pausa" if is_paused else "Gioco")
	return text
",
   "domanda": "Che testo restituisce `run()`?",
   "spiegazione": "`is_paused` passa da `false` a `true` con `not is_paused`. L'operatore ternario seleziona "Pausa" perché la condizione è vera. Il risultato è "Stato: Pausa"."
  },
  {
   "codice": "extends RefCounted


func run():
	var volume: float = 5.0
	var clamped_vol := clampf(volume, -80.0, 0.0)
	return clamped_vol
",
   "domanda": "Quanto vale `clamped_vol`?",
   "spiegazione": "`clampf` forza il valore a rientrare nell'intervallo specificato. Visto che 5.0 è superiore al massimo consentito (0.0), viene limitato a `0.0`."
  }
 ]
}
